#include "stm32f4xx_hal.h"

#define RX_BUF_SIZE     64U
#define LED_PORT        GPIOA
#define LED_PIN         GPIO_PIN_5

UART_HandleTypeDef huart1;

static volatile uint8_t rx_buf[RX_BUF_SIZE];
static volatile uint32_t rx_count;
static uint32_t rx_head;
static uint32_t rx_tail;
static uint8_t rx_byte;

static void uart1_init(void)
{
    GPIO_InitTypeDef gpio = {0};

    __HAL_RCC_GPIOA_CLK_ENABLE();
    __HAL_RCC_USART1_CLK_ENABLE();

    gpio.Pin       = GPIO_PIN_9 | GPIO_PIN_10;
    gpio.Mode      = GPIO_MODE_AF_PP;
    gpio.Pull      = GPIO_PULLUP;
    gpio.Speed     = GPIO_SPEED_FREQ_VERY_HIGH;
    gpio.Alternate = GPIO_AF7_USART1;
    HAL_GPIO_Init(GPIOA, &gpio);

    gpio.Pin       = LED_PIN;
    gpio.Mode      = GPIO_MODE_OUTPUT_PP;
    gpio.Pull      = GPIO_NOPULL;
    gpio.Speed     = GPIO_SPEED_FREQ_LOW;
    gpio.Alternate = 0U;
    HAL_GPIO_Init(LED_PORT, &gpio);

    huart1.Instance          = USART1;
    huart1.Init.BaudRate     = 57600U;
    huart1.Init.WordLength   = UART_WORDLENGTH_8B;
    huart1.Init.StopBits     = UART_STOPBITS_1;
    huart1.Init.Parity       = UART_PARITY_NONE;
    huart1.Init.Mode         = UART_MODE_RX;
    huart1.Init.HwFlowCtl    = UART_HWCONTROL_NONE;
    huart1.Init.OverSampling = UART_OVERSAMPLING_16;
    HAL_UART_Init(&huart1);

    HAL_NVIC_SetPriority(USART1_IRQn, 6, 0);
    HAL_NVIC_EnableIRQ(USART1_IRQn);
}

void USART1_IRQHandler(void)
{
    HAL_UART_IRQHandler(&huart1);
}

void HAL_UART_RxCpltCallback(UART_HandleTypeDef *huart)
{
    if (huart->Instance == USART1) {
        if (rx_count < RX_BUF_SIZE) {
            rx_buf[rx_head] = rx_byte;
            rx_head = (rx_head + 1U) % RX_BUF_SIZE;
            rx_count++;
        }
        HAL_UART_Receive_IT(&huart1, &rx_byte, 1U);
    }
}

static int rx_pop(uint8_t *out)
{
    int have = 0;

    __disable_irq();
    if (rx_count > 0U) {
        *out = rx_buf[rx_tail];
        rx_tail = (rx_tail + 1U) % RX_BUF_SIZE;
        rx_count--;
        have = 1;
    }
    __enable_irq();

    return have;
}

int main(void)
{
    uint8_t c;

    HAL_Init();
    uart1_init();
    HAL_UART_Receive_IT(&huart1, &rx_byte, 1U);

    for (;;) {
        if (rx_pop(&c) != 0) {
            if (c == '!') {
                HAL_GPIO_TogglePin(LED_PORT, LED_PIN);
            }
        }
    }
}

#include "stm32f4xx_hal.h"
#include "FreeRTOS.h"
#include "task.h"
#include "queue.h"

#define LED_PORT        GPIOA
#define LED_PIN         GPIO_PIN_5
#define RX_QUEUE_LEN    32U

UART_HandleTypeDef huart1;

static QueueHandle_t rx_queue;
static uint8_t rx_byte;

static void uart1_init(void)
{
    GPIO_InitTypeDef gpio = {0};

    __HAL_RCC_GPIOA_CLK_ENABLE();
    __HAL_RCC_USART1_CLK_ENABLE();

    gpio.Pin       = GPIO_PIN_9 | GPIO_PIN_10;
    gpio.Mode      = GPIO_MODE_AF_PP;
    gpio.Pull      = GPIO_PULLUP;
    gpio.Speed     = GPIO_SPEED_FREQ_VERY_HIGH;
    gpio.Alternate = GPIO_AF7_USART1;
    HAL_GPIO_Init(GPIOA, &gpio);

    gpio.Pin       = LED_PIN;
    gpio.Mode      = GPIO_MODE_OUTPUT_PP;
    gpio.Pull      = GPIO_NOPULL;
    gpio.Speed     = GPIO_SPEED_FREQ_LOW;
    gpio.Alternate = 0U;
    HAL_GPIO_Init(LED_PORT, &gpio);

    huart1.Instance          = USART1;
    huart1.Init.BaudRate     = 115200U;
    huart1.Init.WordLength   = UART_WORDLENGTH_8B;
    huart1.Init.StopBits     = UART_STOPBITS_1;
    huart1.Init.Parity       = UART_PARITY_NONE;
    huart1.Init.Mode         = UART_MODE_RX;
    huart1.Init.HwFlowCtl    = UART_HWCONTROL_NONE;
    huart1.Init.OverSampling = UART_OVERSAMPLING_16;
    HAL_UART_Init(&huart1);

    HAL_NVIC_SetPriority(USART1_IRQn, 7, 0);
    HAL_NVIC_EnableIRQ(USART1_IRQn);
}

void USART1_IRQHandler(void)
{
    HAL_UART_IRQHandler(&huart1);
}

void HAL_UART_RxCpltCallback(UART_HandleTypeDef *huart)
{
    if (huart->Instance == USART1) {
        xQueueSend(rx_queue, &rx_byte, 0);
        HAL_UART_Receive_IT(&huart1, &rx_byte, 1U);
    }
}

static void command_task(void *arg)
{
    uint8_t c;

    (void)arg;

    for (;;) {
        if (xQueueReceive(rx_queue, &c, portMAX_DELAY) == pdTRUE) {
            if (c == 'l') {
                HAL_GPIO_TogglePin(LED_PORT, LED_PIN);
            }
        }
    }
}

int main(void)
{
    HAL_Init();

    rx_queue = xQueueCreate(RX_QUEUE_LEN, sizeof(uint8_t));
    uart1_init();
    HAL_UART_Receive_IT(&huart1, &rx_byte, 1U);

    xTaskCreate(command_task, "cmd", 128, NULL, 2, NULL);
    vTaskStartScheduler();

    for (;;) {
    }
}

#include "stm32f4xx_hal.h"

#define STATUS_PORT     GPIOC
#define STATUS_PIN      GPIO_PIN_13
#define SENSE_PORT      GPIOA
#define SENSE_PIN       GPIO_PIN_0

UART_HandleTypeDef huart2;

static void gpio_init(void)
{
    GPIO_InitTypeDef gpio = {0};

    __HAL_RCC_GPIOA_CLK_ENABLE();

    gpio.Pin   = SENSE_PIN;
    gpio.Mode  = GPIO_MODE_INPUT;
    gpio.Pull  = GPIO_PULLDOWN;
    HAL_GPIO_Init(SENSE_PORT, &gpio);

    gpio.Pin   = STATUS_PIN;
    gpio.Mode  = GPIO_MODE_OUTPUT_PP;
    gpio.Pull  = GPIO_NOPULL;
    gpio.Speed = GPIO_SPEED_FREQ_LOW;
    HAL_GPIO_Init(STATUS_PORT, &gpio);
}

static void uart2_init(void)
{
    GPIO_InitTypeDef gpio = {0};

    __HAL_RCC_GPIOA_CLK_ENABLE();
    __HAL_RCC_USART2_CLK_ENABLE();

    gpio.Pin       = GPIO_PIN_2;
    gpio.Mode      = GPIO_MODE_AF_PP;
    gpio.Pull      = GPIO_NOPULL;
    gpio.Speed     = GPIO_SPEED_FREQ_VERY_HIGH;
    gpio.Alternate = GPIO_AF7_USART2;
    HAL_GPIO_Init(GPIOA, &gpio);

    huart2.Instance          = USART2;
    huart2.Init.BaudRate     = 115200U;
    huart2.Init.WordLength   = UART_WORDLENGTH_8B;
    huart2.Init.StopBits     = UART_STOPBITS_1;
    huart2.Init.Parity       = UART_PARITY_NONE;
    huart2.Init.Mode         = UART_MODE_TX;
    huart2.Init.HwFlowCtl    = UART_HWCONTROL_NONE;
    huart2.Init.OverSampling = UART_OVERSAMPLING_16;
    HAL_UART_Init(&huart2);
}

int main(void)
{
    static uint8_t on_msg[]  = "sense: high\r\n";
    static uint8_t off_msg[] = "sense: low\r\n";

    HAL_Init();
    gpio_init();
    uart2_init();

    for (;;) {
        if (HAL_GPIO_ReadPin(SENSE_PORT, SENSE_PIN) == GPIO_PIN_SET) {
            HAL_GPIO_WritePin(STATUS_PORT, STATUS_PIN, GPIO_PIN_SET);
            HAL_UART_Transmit(&huart2, on_msg, (uint16_t)(sizeof(on_msg) - 1U), 50U);
        } else {
            HAL_GPIO_WritePin(STATUS_PORT, STATUS_PIN, GPIO_PIN_RESET);
            HAL_UART_Transmit(&huart2, off_msg, (uint16_t)(sizeof(off_msg) - 1U), 50U);
        }
        HAL_Delay(1000U);
    }
}

#include "stm32f4xx_hal.h"
#include <stdio.h>

#define UART_PORT       GPIOA
#define LED_PORT        GPIOB
#define LED_PIN         GPIO_PIN_0

UART_HandleTypeDef huart2;

static void gpio_init(void)
{
    GPIO_InitTypeDef gpio = {0};

    __HAL_RCC_GPIOA_CLK_ENABLE();
    __HAL_RCC_GPIOB_CLK_ENABLE();

    gpio.Pin   = LED_PIN;
    gpio.Mode  = GPIO_MODE_OUTPUT_PP;
    gpio.Pull  = GPIO_NOPULL;
    gpio.Speed = GPIO_SPEED_FREQ_LOW;
    HAL_GPIO_Init(LED_PORT, &gpio);

    gpio.Pin       = GPIO_PIN_2 | GPIO_PIN_3;
    gpio.Mode      = GPIO_MODE_AF_PP;
    gpio.Pull      = GPIO_PULLUP;
    gpio.Speed     = GPIO_SPEED_FREQ_VERY_HIGH;
    gpio.Alternate = GPIO_AF4_I2C1;
    HAL_GPIO_Init(UART_PORT, &gpio);
}

static void uart2_init(void)
{
    __HAL_RCC_USART2_CLK_ENABLE();

    huart2.Instance          = USART2;
    huart2.Init.BaudRate     = 115200U;
    huart2.Init.WordLength   = UART_WORDLENGTH_8B;
    huart2.Init.StopBits     = UART_STOPBITS_1;
    huart2.Init.Parity       = UART_PARITY_NONE;
    huart2.Init.Mode         = UART_MODE_TX_RX;
    huart2.Init.HwFlowCtl    = UART_HWCONTROL_NONE;
    huart2.Init.OverSampling = UART_OVERSAMPLING_16;
    HAL_UART_Init(&huart2);
}

int main(void)
{
    char line[32];
    uint32_t count = 0U;
    int n;

    HAL_Init();
    gpio_init();
    uart2_init();

    for (;;) {
        n = snprintf(line, sizeof(line), "frame %lu\r\n", (unsigned long)count);
        HAL_UART_Transmit(&huart2, (uint8_t *)line, (uint16_t)n, 100U);
        HAL_GPIO_TogglePin(LED_PORT, LED_PIN);
        count++;
        HAL_Delay(500U);
    }
}

#include "stm32f4xx_hal.h"
#include <stdio.h>

#define LED_PORT        GPIOA
#define LED_PIN         GPIO_PIN_5

UART_HandleTypeDef huart6;

static volatile uint8_t tx_done;

static void uart6_init(void)
{
    GPIO_InitTypeDef gpio = {0};

    __HAL_RCC_GPIOA_CLK_ENABLE();
    __HAL_RCC_USART6_CLK_ENABLE();

    gpio.Pin       = GPIO_PIN_11;
    gpio.Mode      = GPIO_MODE_AF_PP;
    gpio.Pull      = GPIO_NOPULL;
    gpio.Speed     = GPIO_SPEED_FREQ_HIGH;
    gpio.Alternate = GPIO_AF8_USART6;
    HAL_GPIO_Init(GPIOA, &gpio);

    gpio.Pin       = LED_PIN;
    gpio.Mode      = GPIO_MODE_OUTPUT_PP;
    gpio.Speed     = GPIO_SPEED_FREQ_LOW;
    gpio.Alternate = 0U;
    HAL_GPIO_Init(LED_PORT, &gpio);

    huart6.Instance          = USART6;
    huart6.Init.BaudRate     = 19200U;
    huart6.Init.WordLength   = UART_WORDLENGTH_8B;
    huart6.Init.StopBits     = UART_STOPBITS_1;
    huart6.Init.Parity       = UART_PARITY_NONE;
    huart6.Init.Mode         = UART_MODE_TX;
    huart6.Init.HwFlowCtl    = UART_HWCONTROL_NONE;
    huart6.Init.OverSampling = UART_OVERSAMPLING_16;
    HAL_UART_Init(&huart6);

    HAL_NVIC_SetPriority(USART6_IRQn, 6, 0);
    HAL_NVIC_EnableIRQ(USART6_IRQn);
}

void USART6_IRQHandler(void)
{
    HAL_UART_IRQHandler(&huart6);
}

void HAL_UART_TxCpltCallback(UART_HandleTypeDef *huart)
{
    if (huart->Instance == USART6) {
        tx_done = 1U;
    }
}

static void send_value(uint32_t value)
{
    char line[40];
    int n;

    n = snprintf(line, sizeof(line), "value=%lu\r\n", (unsigned long)value);

    tx_done = 0U;
    HAL_UART_Transmit_IT(&huart6, (uint8_t *)line, (uint16_t)n);

    while (tx_done == 0U) {
    }
}

int main(void)
{
    uint32_t value = 0U;

    HAL_Init();
    uart6_init();

    for (;;) {
        send_value(value);
        value += 3U;
        HAL_GPIO_TogglePin(LED_PORT, LED_PIN);
        HAL_Delay(500U);
    }
}

#include "stm32f4xx_hal.h"

#define LIGHT_PORT      GPIOA
#define LIGHT_PIN       GPIO_PIN_1
#define BACKLIGHT_PORT  GPIOA
#define BACKLIGHT_PIN   GPIO_PIN_4
#define DARK_LEVEL      900U

ADC_HandleTypeDef hadc1;

static void gpio_init(void)
{
    GPIO_InitTypeDef gpio = {0};

    __HAL_RCC_GPIOA_CLK_ENABLE();

    gpio.Pin  = LIGHT_PIN | BACKLIGHT_PIN;
    gpio.Mode = GPIO_MODE_ANALOG;
    gpio.Pull = GPIO_NOPULL;
    HAL_GPIO_Init(GPIOA, &gpio);
}

static void adc1_init(void)
{
    ADC_ChannelConfTypeDef ch = {0};

    __HAL_RCC_ADC1_CLK_ENABLE();

    hadc1.Instance                   = ADC1;
    hadc1.Init.ClockPrescaler        = ADC_CLOCK_SYNC_PCLK_DIV6;
    hadc1.Init.Resolution            = ADC_RESOLUTION_12B;
    hadc1.Init.ScanConvMode          = DISABLE;
    hadc1.Init.ContinuousConvMode    = DISABLE;
    hadc1.Init.DiscontinuousConvMode = DISABLE;
    hadc1.Init.ExternalTrigConvEdge  = ADC_EXTERNALTRIGCONVEDGE_NONE;
    hadc1.Init.ExternalTrigConv      = ADC_SOFTWARE_START;
    hadc1.Init.DataAlign             = ADC_DATAALIGN_RIGHT;
    hadc1.Init.NbrOfConversion       = 1U;
    hadc1.Init.DMAContinuousRequests = DISABLE;
    hadc1.Init.EOCSelection          = ADC_EOC_SINGLE_CONV;
    HAL_ADC_Init(&hadc1);

    ch.Channel      = ADC_CHANNEL_1;
    ch.Rank         = 1U;
    ch.SamplingTime = ADC_SAMPLETIME_144CYCLES;
    HAL_ADC_ConfigChannel(&hadc1, &ch);
}

static uint32_t read_light(void)
{
    uint32_t value = 0U;

    HAL_ADC_Start(&hadc1);
    if (HAL_ADC_PollForConversion(&hadc1, 10U) == HAL_OK) {
        value = HAL_ADC_GetValue(&hadc1);
    }
    HAL_ADC_Stop(&hadc1);

    return value;
}

int main(void)
{
    HAL_Init();
    gpio_init();
    adc1_init();

    for (;;) {
        uint32_t light = read_light();

        HAL_GPIO_WritePin(BACKLIGHT_PORT, BACKLIGHT_PIN,
                          (light < DARK_LEVEL) ? GPIO_PIN_SET : GPIO_PIN_RESET);
        HAL_Delay(100U);
    }
}

#include "stm32f4xx_hal.h"
#include "FreeRTOS.h"
#include "task.h"
#include "semphr.h"

#define LED_PORT        GPIOA
#define LED_PIN         GPIO_PIN_5
#define RELAY_PORT      GPIOB
#define RELAY_PIN       GPIO_PIN_6
#define FAULT_PORT      GPIOB
#define FAULT_PIN       GPIO_PIN_2

TIM_HandleTypeDef htim4;

static SemaphoreHandle_t tick_sem;
static volatile uint8_t fault_latched;

static void gpio_init(void)
{
    GPIO_InitTypeDef gpio = {0};

    __HAL_RCC_GPIOA_CLK_ENABLE();
    __HAL_RCC_GPIOB_CLK_ENABLE();

    gpio.Pin   = LED_PIN;
    gpio.Mode  = GPIO_MODE_OUTPUT_PP;
    gpio.Pull  = GPIO_NOPULL;
    gpio.Speed = GPIO_SPEED_FREQ_LOW;
    HAL_GPIO_Init(LED_PORT, &gpio);

    gpio.Pin = RELAY_PIN;
    HAL_GPIO_Init(RELAY_PORT, &gpio);
    HAL_GPIO_WritePin(RELAY_PORT, RELAY_PIN, GPIO_PIN_SET);

    gpio.Pin  = FAULT_PIN;
    gpio.Mode = GPIO_MODE_IT_FALLING;
    gpio.Pull = GPIO_PULLUP;
    HAL_GPIO_Init(FAULT_PORT, &gpio);

    HAL_NVIC_SetPriority(EXTI2_IRQn, 1, 0);
    HAL_NVIC_EnableIRQ(EXTI2_IRQn);
}

static void timer4_init(void)
{
    __HAL_RCC_TIM4_CLK_ENABLE();

    htim4.Instance               = TIM4;
    htim4.Init.Prescaler         = 15999U;
    htim4.Init.CounterMode       = TIM_COUNTERMODE_UP;
    htim4.Init.Period            = 99U;
    htim4.Init.ClockDivision     = TIM_CLOCKDIVISION_DIV1;
    htim4.Init.AutoReloadPreload = TIM_AUTORELOAD_PRELOAD_DISABLE;
    HAL_TIM_Base_Init(&htim4);

    HAL_NVIC_SetPriority(TIM4_IRQn, 6, 0);
    HAL_NVIC_EnableIRQ(TIM4_IRQn);
}

void EXTI2_IRQHandler(void)
{
    HAL_GPIO_EXTI_IRQHandler(FAULT_PIN);
}

void TIM4_IRQHandler(void)
{
    HAL_TIM_IRQHandler(&htim4);
}

void HAL_GPIO_EXTI_Callback(uint16_t pin)
{
    if (pin == FAULT_PIN) {
        HAL_GPIO_WritePin(RELAY_PORT, RELAY_PIN, GPIO_PIN_RESET);
        fault_latched = 1U;
    }
}

void HAL_TIM_PeriodElapsedCallback(TIM_HandleTypeDef *htim)
{
    BaseType_t woken = pdFALSE;

    if (htim->Instance == TIM4) {
        xSemaphoreGiveFromISR(tick_sem, &woken);
    }
    portYIELD_FROM_ISR(woken);
}

static void supervisor_task(void *arg)
{
    (void)arg;

    for (;;) {
        if (xSemaphoreTake(tick_sem, portMAX_DELAY) == pdTRUE) {
            if (fault_latched != 0U) {
                HAL_GPIO_WritePin(LED_PORT, LED_PIN, GPIO_PIN_SET);
            } else {
                HAL_GPIO_TogglePin(LED_PORT, LED_PIN);
            }
        }
    }
}

int main(void)
{
    HAL_Init();

    tick_sem = xSemaphoreCreateBinary();
    gpio_init();
    timer4_init();

    xTaskCreate(supervisor_task, "super", 128, NULL, 2, NULL);
    HAL_TIM_Base_Start_IT(&htim4);
    vTaskStartScheduler();

    for (;;) {
    }
}

#include "stm32f4xx_hal.h"

#define LED_PORT        GPIOA
#define LED_PIN         GPIO_PIN_5
#define REPORT_PERIOD   400U

UART_HandleTypeDef huart1;
TIM_HandleTypeDef htim3;

void HAL_UART_MspInit(UART_HandleTypeDef *huart)
{
    GPIO_InitTypeDef gpio = {0};

    if (huart->Instance == USART1) {
        __HAL_RCC_GPIOA_CLK_ENABLE();
        __HAL_RCC_USART1_CLK_ENABLE();

        gpio.Pin       = GPIO_PIN_9 | GPIO_PIN_10;
        gpio.Mode      = GPIO_MODE_AF_PP;
