{
    BaseType_t woken = pdFALSE;

    if (pin == BTN_PIN) {
        vTaskDelay(pdMS_TO_TICKS(SETTLE_MS));
        if (HAL_GPIO_ReadPin(BTN_PORT, BTN_PIN) == GPIO_PIN_RESET) {
            xSemaphoreGiveFromISR(press_sem, &woken);
