{
    uint8_t frame[4];

    frame[0] = 0x40U;
    frame[1] = level;
    frame[2] = (uint8_t)~level;
    frame[3] = 0x00U;

    HAL_GPIO_WritePin(CS_PORT, CS_PIN, GPIO_PIN_RESET);
    HAL_SPI_Transmit_IT(&hspi1, frame, 4U);
}

