static int sensor_read(uint8_t reg, uint8_t *out)
{
    if (xSemaphoreTake(bus_mutex, pdMS_TO_TICKS(20)) != pdTRUE) {
        return -1;
    }

    if (HAL_I2C_Master_Transmit(&hi2c1, SENSOR_ADDR, &reg, 1U, 20U) != HAL_OK) {
