    HAL_Init();
    gpio_init();
    timer2_init();

    for (;;) {
        uint32_t width = latest.width_us;
        uint32_t stamp = latest.stamp_ms;

        if (stamp != last_stamp) {
            last_stamp = stamp;
            HAL_GPIO_WritePin(LED_PORT, LED_PIN,
                              (width > (1000U + MAX_JITTER_US)) ? GPIO_PIN_SET : GPIO_PIN_RESET);
        }
    }
}

