{
    HAL_Init();
    uart2_init();
    HAL_UART_Receive_IT(&huart2, &rx_byte, 1U);

    for (;;) {
        if (rx_count > 0U) {
            uint8_t b = rx_buf[rx_tail];
            rx_tail = (uint8_t)((rx_tail + 1U) % RX_BUF_LEN);
            rx_count--;
            handle_byte(b);
        }
    }
}

