#include "stm32f4xx_hal.h"
#include "FreeRTOS.h"
#include "task.h"
#include "semphr.h"

#define SENSOR_ADDR     (0x48U << 1)
#define REG_TEMP        0x00U
#define ALARM_LIMIT     600
#define LED_PORT        GPIOC
#define LED_PIN         GPIO_PIN_13

I2C_HandleTypeDef hi2c1;

static SemaphoreHandle_t i2c_mutex;
static int16_t last_temp;

static void board_init(void)
{
    GPIO_InitTypeDef gpio = {0};

    __HAL_RCC_GPIOB_CLK_ENABLE();
    __HAL_RCC_GPIOC_CLK_ENABLE();
    __HAL_RCC_I2C1_CLK_ENABLE();

    gpio.Pin       = GPIO_PIN_8 | GPIO_PIN_9;
    gpio.Mode      = GPIO_MODE_AF_OD;
    gpio.Pull      = GPIO_PULLUP;
    gpio.Speed     = GPIO_SPEED_FREQ_HIGH;
    gpio.Alternate = GPIO_AF4_I2C1;
    HAL_GPIO_Init(GPIOB, &gpio);

    gpio.Pin       = LED_PIN;
    gpio.Mode      = GPIO_MODE_OUTPUT_PP;
    gpio.Pull      = GPIO_NOPULL;
    gpio.Speed     = GPIO_SPEED_FREQ_LOW;
    HAL_GPIO_Init(LED_PORT, &gpio);

    hi2c1.Instance             = I2C1;
    hi2c1.Init.ClockSpeed      = 100000U;
    hi2c1.Init.DutyCycle       = I2C_DUTYCYCLE_2;
    hi2c1.Init.AddressingMode  = I2C_ADDRESSINGMODE_7BIT;
    hi2c1.Init.NoStretchMode   = I2C_NOSTRETCH_DISABLE;
    HAL_I2C_Init(&hi2c1);
}

static int32_t sensor_read_temp(int16_t *out)
{
    uint8_t raw[2];

    if (xSemaphoreTake(i2c_mutex, pdMS_TO_TICKS(50)) != pdTRUE) {
        return -1;
    }
    if (HAL_I2C_Mem_Read(&hi2c1, SENSOR_ADDR, REG_TEMP, I2C_MEMADD_SIZE_8BIT, raw, 2U, 20U) != HAL_OK) {
        return -2;
    }
    *out = (int16_t)(((uint16_t)raw[0] << 8) | raw[1]);
    xSemaphoreGive(i2c_mutex);
    return 0;
}

static void temp_task(void *arg)
{
    int16_t t;
    (void)arg;

    for (;;) {
        if (sensor_read_temp(&t) == 0) {
            last_temp = t;
            if (t > ALARM_LIMIT) {
                HAL_GPIO_WritePin(LED_PORT, LED_PIN, GPIO_PIN_SET);
            } else {
                HAL_GPIO_WritePin(LED_PORT, LED_PIN, GPIO_PIN_RESET);
            }
        }
        vTaskDelay(pdMS_TO_TICKS(250));
    }
}

int main(void)
{
    HAL_Init();
    board_init();

    i2c_mutex = xSemaphoreCreateMutex();
    xTaskCreate(temp_task, "temp", 256, NULL, 2, NULL);
    vTaskStartScheduler();

    for (;;) {
    }
}

#include "stm32f4xx_hal.h"
#include <string.h>

#define FRAME_LEN       32U
#define PAYLOAD_LEN     16U
#define CMD_SET_CFG     0x21U
#define LED_PORT        GPIOA
#define LED_PIN         GPIO_PIN_5

UART_HandleTypeDef huart1;

static uint8_t rx_frame[FRAME_LEN];
static uint8_t cfg_payload[PAYLOAD_LEN];
static uint8_t cfg_valid;

static void uart1_init(void)
{
    GPIO_InitTypeDef gpio = {0};

    __HAL_RCC_GPIOA_CLK_ENABLE();
    __HAL_RCC_USART1_CLK_ENABLE();

    gpio.Pin       = GPIO_PIN_9 | GPIO_PIN_10;
    gpio.Mode      = GPIO_MODE_AF_PP;
    gpio.Pull      = GPIO_PULLUP;
    gpio.Speed     = GPIO_SPEED_FREQ_HIGH;
    gpio.Alternate = GPIO_AF7_USART1;
    HAL_GPIO_Init(GPIOA, &gpio);

    gpio.Pin       = LED_PIN;
    gpio.Mode      = GPIO_MODE_OUTPUT_PP;
    gpio.Pull      = GPIO_NOPULL;
    gpio.Alternate = 0U;
    HAL_GPIO_Init(LED_PORT, &gpio);

    huart1.Instance          = USART1;
    huart1.Init.BaudRate     = 115200U;
    huart1.Init.WordLength   = UART_WORDLENGTH_8B;
    huart1.Init.StopBits     = UART_STOPBITS_1;
    huart1.Init.Parity       = UART_PARITY_NONE;
    huart1.Init.Mode         = UART_MODE_TX_RX;
    huart1.Init.HwFlowCtl    = UART_HWCONTROL_NONE;
    huart1.Init.OverSampling = UART_OVERSAMPLING_16;
    HAL_UART_Init(&huart1);
}

static uint8_t checksum(const uint8_t *p, uint32_t n)
{
    uint8_t sum = 0U;
    uint32_t i;

    for (i = 0U; i < n; i++) {
        sum = (uint8_t)(sum + p[i]);
    }
    return sum;
}

static void handle_frame(void)
{
    uint8_t len;

    if (rx_frame[0] != CMD_SET_CFG) {
        return;
    }
    len = rx_frame[1];
    memcpy(cfg_payload, &rx_frame[2], len);
    cfg_valid = (checksum(cfg_payload, PAYLOAD_LEN) == rx_frame[FRAME_LEN - 1U]) ? 1U : 0U;
}

int main(void)
{
    HAL_Init();
    uart1_init();

    for (;;) {
        if (HAL_UART_Receive(&huart1, rx_frame, FRAME_LEN, 500U) == HAL_OK) {
            handle_frame();
            if (cfg_valid != 0U) {
                HAL_GPIO_TogglePin(LED_PORT, LED_PIN);
            }
        }
    }
}

#include "stm32f4xx_hal.h"

#define BTN_PORT        GPIOC
#define BTN_PIN         GPIO_PIN_13
#define LED_PORT        GPIOA
#define LED_PIN         GPIO_PIN_5
#define DEBOUNCE_MS     20U
#define LONG_PRESS_MS   800U

static volatile uint32_t last_press_tick;

static void gpio_init(void)
{
    GPIO_InitTypeDef gpio = {0};

    __HAL_RCC_GPIOA_CLK_ENABLE();
    __HAL_RCC_GPIOC_CLK_ENABLE();

    gpio.Pin   = LED_PIN;
    gpio.Mode  = GPIO_MODE_OUTPUT_PP;
    gpio.Pull  = GPIO_NOPULL;
    gpio.Speed = GPIO_SPEED_FREQ_LOW;
    HAL_GPIO_Init(LED_PORT, &gpio);

    gpio.Pin  = BTN_PIN;
    gpio.Mode = GPIO_MODE_IT_FALLING;
    gpio.Pull = GPIO_PULLUP;
    HAL_GPIO_Init(BTN_PORT, &gpio);

    HAL_NVIC_SetPriority(EXTI15_10_IRQn, 6, 0);
    HAL_NVIC_EnableIRQ(EXTI15_10_IRQn);
}

void EXTI15_10_IRQHandler(void)
{
    HAL_GPIO_EXTI_IRQHandler(BTN_PIN);
}

void HAL_GPIO_EXTI_Callback(uint16_t pin)
{
    if (pin == BTN_PIN) {
        HAL_Delay(DEBOUNCE_MS);
        if (HAL_GPIO_ReadPin(BTN_PORT, BTN_PIN) == GPIO_PIN_RESET) {
            last_press_tick = HAL_GetTick();
        }
    }
}

int main(void)
{
    uint32_t seen = 0U;

    HAL_Init();
    gpio_init();

    for (;;) {
        uint32_t t = last_press_tick;

        if (t != seen) {
            seen = t;
            HAL_GPIO_WritePin(LED_PORT, LED_PIN, GPIO_PIN_SET);
            HAL_Delay(LONG_PRESS_MS);
            HAL_GPIO_WritePin(LED_PORT, LED_PIN, GPIO_PIN_RESET);
        }
    }
}

#include "stm32f4xx_hal.h"
#include "FreeRTOS.h"
#include "task.h"
#include "semphr.h"

#define CS_PORT         GPIOA
#define CS_PIN          GPIO_PIN_4
#define CMD_READ_ID     0x9FU

SPI_HandleTypeDef hspi1;

static SemaphoreHandle_t spi_mutex;
static uint32_t flash_id;

static void spi1_init(void)
{
    GPIO_InitTypeDef gpio = {0};

    __HAL_RCC_GPIOA_CLK_ENABLE();
    __HAL_RCC_SPI1_CLK_ENABLE();

    gpio.Pin       = GPIO_PIN_5 | GPIO_PIN_6 | GPIO_PIN_7;
    gpio.Mode      = GPIO_MODE_AF_PP;
    gpio.Pull      = GPIO_NOPULL;
    gpio.Speed     = GPIO_SPEED_FREQ_HIGH;
    gpio.Alternate = GPIO_AF5_SPI1;
    HAL_GPIO_Init(GPIOA, &gpio);

    gpio.Pin       = CS_PIN;
    gpio.Mode      = GPIO_MODE_OUTPUT_PP;
    gpio.Alternate = 0U;
    HAL_GPIO_Init(CS_PORT, &gpio);
    HAL_GPIO_WritePin(CS_PORT, CS_PIN, GPIO_PIN_SET);

    hspi1.Instance               = SPI1;
    hspi1.Init.Mode              = SPI_MODE_MASTER;
    hspi1.Init.Direction         = SPI_DIRECTION_2LINES;
    hspi1.Init.DataSize          = SPI_DATASIZE_8BIT;
    hspi1.Init.CLKPolarity       = SPI_POLARITY_LOW;
    hspi1.Init.CLKPhase          = SPI_PHASE_1EDGE;
    hspi1.Init.NSS               = SPI_NSS_SOFT;
    hspi1.Init.BaudRatePrescaler = SPI_BAUDRATEPRESCALER_8;
    hspi1.Init.FirstBit          = SPI_FIRSTBIT_MSB;
    HAL_SPI_Init(&hspi1);
}

static int flash_read_id(uint32_t *id)
{
    int rc = -1;
    uint8_t cmd = CMD_READ_ID;
    uint8_t buf[3];

    if (xSemaphoreTake(spi_mutex, pdMS_TO_TICKS(50)) != pdTRUE) {
        return -1;
    }
    HAL_GPIO_WritePin(CS_PORT, CS_PIN, GPIO_PIN_RESET);
    if (HAL_SPI_Transmit(&hspi1, &cmd, 1U, 20U) != HAL_OK) {
        goto out;
    }
    if (HAL_SPI_Receive(&hspi1, buf, 3U, 20U) != HAL_OK) {
        goto out;
    }
    *id = ((uint32_t)buf[0] << 16) | ((uint32_t)buf[1] << 8) | buf[2];
    rc = 0;
out:
    HAL_GPIO_WritePin(CS_PORT, CS_PIN, GPIO_PIN_SET);
    xSemaphoreGive(spi_mutex);
    return rc;
}

static void flash_task(void *arg)
{
    uint32_t id;
    (void)arg;

    for (;;) {
        if (flash_read_id(&id) == 0) {
            flash_id = id;
        }
        vTaskDelay(pdMS_TO_TICKS(1000));
    }
}

int main(void)
{
    HAL_Init();
    spi1_init();

    spi_mutex = xSemaphoreCreateMutex();
    xTaskCreate(flash_task, "flash", 256, NULL, 2, NULL);
    vTaskStartScheduler();

    for (;;) {
    }
}

#include "stm32f4xx_hal.h"

#define RING_LEN        32U
#define WINDOW          8U
#define LED_PORT        GPIOB
#define LED_PIN         GPIO_PIN_7
#define LIMIT           3000U

ADC_HandleTypeDef hadc1;

static uint16_t ring[RING_LEN];
static uint32_t head;
static uint32_t filled;

static void adc_init(void)
{
    GPIO_InitTypeDef gpio = {0};
    ADC_ChannelConfTypeDef ch = {0};

    __HAL_RCC_GPIOA_CLK_ENABLE();
    __HAL_RCC_GPIOB_CLK_ENABLE();
    __HAL_RCC_ADC1_CLK_ENABLE();

    gpio.Pin  = GPIO_PIN_1;
    gpio.Mode = GPIO_MODE_ANALOG;
    gpio.Pull = GPIO_NOPULL;
    HAL_GPIO_Init(GPIOA, &gpio);

    gpio.Pin   = LED_PIN;
    gpio.Mode  = GPIO_MODE_OUTPUT_PP;
    gpio.Speed = GPIO_SPEED_FREQ_LOW;
    HAL_GPIO_Init(LED_PORT, &gpio);

    hadc1.Instance                = ADC1;
    hadc1.Init.ClockPrescaler     = ADC_CLOCK_SYNC_PCLK_DIV4;
    hadc1.Init.Resolution         = ADC_RESOLUTION_12B;
    hadc1.Init.ScanConvMode       = DISABLE;
    hadc1.Init.ContinuousConvMode = DISABLE;
    hadc1.Init.ExternalTrigConv   = ADC_SOFTWARE_START;
    hadc1.Init.DataAlign          = ADC_DATAALIGN_RIGHT;
    hadc1.Init.NbrOfConversion    = 1U;
    HAL_ADC_Init(&hadc1);

    ch.Channel      = ADC_CHANNEL_1;
    ch.Rank         = 1U;
    ch.SamplingTime = ADC_SAMPLETIME_56CYCLES;
    HAL_ADC_ConfigChannel(&hadc1, &ch);
}

static void ring_push(uint16_t v)
{
    ring[head] = v;
    head = (head + 1U) % RING_LEN;
    if (filled < RING_LEN) {
        filled++;
    }
}

static uint32_t window_average(void)
{
    uint32_t n = (filled < WINDOW) ? filled : WINDOW;
    uint32_t sum = 0U;
    uint32_t i;

    if (n == 0U) {
        return 0U;
    }
    for (i = 0U; i < n; i++) {
        uint32_t idx = (head + RING_LEN - 1U - i) % RING_LEN;
        sum += ring[idx];
    }
    return sum / n;
}

int main(void)
{
    HAL_Init();
    adc_init();

    for (;;) {
        HAL_ADC_Start(&hadc1);
        if (HAL_ADC_PollForConversion(&hadc1, 10U) == HAL_OK) {
            ring_push((uint16_t)HAL_ADC_GetValue(&hadc1));
        }
        HAL_ADC_Stop(&hadc1);

        if (window_average() > LIMIT) {
            HAL_GPIO_WritePin(LED_PORT, LED_PIN, GPIO_PIN_SET);
        } else {
            HAL_GPIO_WritePin(LED_PORT, LED_PIN, GPIO_PIN_RESET);
        }
        HAL_Delay(20U);
    }
}

#include "stm32f4xx_hal.h"
#include <stdio.h>

#define LED_PORT        GPIOA
#define LED_PIN         GPIO_PIN_5
#define REPORT_PERIOD   500U

UART_HandleTypeDef huart2;

static volatile uint8_t tx_done;

static void uart2_init(void)
{
    GPIO_InitTypeDef gpio = {0};

    __HAL_RCC_GPIOA_CLK_ENABLE();
    __HAL_RCC_USART2_CLK_ENABLE();

    gpio.Pin       = GPIO_PIN_2 | GPIO_PIN_3;
    gpio.Mode      = GPIO_MODE_AF_PP;
    gpio.Pull      = GPIO_PULLUP;
    gpio.Speed     = GPIO_SPEED_FREQ_HIGH;
    gpio.Alternate = GPIO_AF7_USART2;
    HAL_GPIO_Init(GPIOA, &gpio);

    gpio.Pin       = LED_PIN;
    gpio.Mode      = GPIO_MODE_OUTPUT_PP;
    gpio.Pull      = GPIO_NOPULL;
    gpio.Alternate = 0U;
    HAL_GPIO_Init(LED_PORT, &gpio);

    huart2.Instance          = USART2;
    huart2.Init.BaudRate     = 115200U;
    huart2.Init.WordLength   = UART_WORDLENGTH_8B;
    huart2.Init.StopBits     = UART_STOPBITS_1;
    huart2.Init.Parity       = UART_PARITY_NONE;
    huart2.Init.Mode         = UART_MODE_TX;
    huart2.Init.HwFlowCtl    = UART_HWCONTROL_NONE;
    huart2.Init.OverSampling = UART_OVERSAMPLING_16;
    HAL_UART_Init(&huart2);

